package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="architecture_diagrams") public class ArchitectureDiagram { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="candidate_id",unique=true) private ArchitectureCandidate candidate; @Lob private String plantUmlSource; @Lob private String svg; @Column(nullable=false) private Instant createdAt=Instant.now(); public ArchitectureDiagram(){} public ArchitectureDiagram(ArchitectureCandidate c,String s,String v){candidate=c;plantUmlSource=s;svg=v;} }
